function cropBox(width, height, targetRatio, focus) {
  const fx = focus?.x ?? 0.5;
  const fy = focus?.y ?? 0.5;
  const srcRatio = width / height;
  let cropW, cropH;
  if (srcRatio > targetRatio) { cropH = height; cropW = Math.round(height * targetRatio); }
  else { cropW = width; cropH = Math.round(width / targetRatio); }
  let left = Math.round(fx * width - cropW / 2);
  let top = Math.round(fy * height - cropH / 2);
  left = Math.min(Math.max(left, 0), width - cropW);
  top = Math.min(Math.max(top, 0), height - cropH);
  return { left, top, width: cropW, height: cropH };
}
function even(n) { return n % 2 === 0 ? n : n - 1; }
function fitWithoutUpscale(cropW, cropH, maxW, maxH) {
  if (cropW <= maxW && cropH <= maxH) return { width: cropW, height: cropH };
  const scale = Math.min(maxW / cropW, maxH / cropH);
  return { width: even(Math.floor(cropW * scale)), height: even(Math.floor(cropH * scale)) };
}
function parseFocus(raw) {
  try {
    let t = raw?.content ?? raw?.text ?? raw?.[0]?.content?.[0]?.text ?? raw?.output?.[0]?.content?.[0]?.text ?? raw;
    if (typeof t !== 'string') t = JSON.stringify(t);
    const m = t.match(/\{[\s\S]*\}/);
    if (!m) return { x: 0.5, y: 0.5 };
    const j = JSON.parse(m[0]);
    return { x: Number(j.x) || 0.5, y: Number(j.y) || 0.5 };
  } catch (e) { return { x: 0.5, y: 0.5 }; }
}
function readSize(info) {
  const width = Number(info?.size?.width || info?.width || info?.data?.width || 0);
  const height = Number(info?.size?.height || info?.height || info?.data?.height || 0);
  if (width > 0 && height > 0) return { width, height };
  const geo = String(info?.Geometry || '');
  const m = geo.match(/^(\d+)x(\d+)/);
  if (m) return { width: Number(m[1]), height: Number(m[2]) };
  throw new Error('Feature Image Info missing size: ' + JSON.stringify(Object.keys(info || {})));
}
const trigger = $('Adapt Feature Trigger').first().json;
const slug = String(trigger.slug || '');
const { width, height } = readSize($('Feature Image Info').first().json);
const focus = parseFocus($('Feature Crop Focus').first().json);
const jobs = [];
{
  const box = cropBox(width, height, 1080 / 1350, focus);
  const out = fitWithoutUpscale(box.width, box.height, 1080, 1350);
  jobs.push({ platform: 'instagram', crop: box, out, sftp_path: '/syndicator/' + slug + '/header/instagram.jpg' });
}
for (const platform of ['facebook', 'x']) {
  let outW = width, outH = height;
  const maxEdge = Math.max(width, height);
  if (maxEdge > 2048) {
    const scale = 2048 / maxEdge;
    outW = even(Math.floor(width * scale));
    outH = even(Math.floor(height * scale));
  }
  jobs.push({ platform, crop: { left: 0, top: 0, width, height }, out: { width: outW, height: outH }, sftp_path: '/syndicator/' + slug + '/header/' + platform + '.jpg' });
}
return jobs.map((j) => ({ json: j }));

